package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Tenant    string `json:"tenant"`
	FieldName string `json:"field_name"`
	Value     string `json:"value"`
	OrderBy   string `json:"order_by"`
}

type Record struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
	Data  string `json:"data"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeIdentifier attempts to prevent SQL injection in identifiers
// by checking against known columns - but the check is flawed
func sanitizeIdentifier(input string) string {
	allowed := []string{"name", "email", "created_at", "status", "department"}
	lower := strings.ToLower(strings.TrimSpace(input))
	for _, col := range allowed {
		if lower == col {
			return input
		}
	}
	return "name" // default fallback
}

// buildSearchQuery constructs a dynamic query for multi-tenant search
func buildSearchQuery(req SearchRequest) string {
	// Tenant isolation via schema - tenant value is used directly
	// Developer assumes tenant comes from authenticated session
	schema := fmt.Sprintf("%s", req.Tenant)

	// Field name is validated
	field := sanitizeIdentifier(req.FieldName)

	// ORDER BY uses sanitizeIdentifier too
	orderCol := sanitizeIdentifier(req.OrderBy)

	// BUG: The 'Value' field is interpolated directly into the query
	// Developer thought the ORM would handle it but used fmt.Sprintf instead
	query := fmt.Sprintf(
		"SELECT id, name, email, data FROM %s.records WHERE %s = '%s' ORDER BY %s LIMIT 50",
		schema, field, req.Value, orderCol,
	)
	return query
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	// Tenant is extracted from request body (should come from auth middleware)
	if req.Tenant == "" {
		http.Error(w, "Tenant required", 400)
		return
	}

	query := buildSearchQuery(req)
	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []Record
	for rows.Next() {
		var rec Record
		if err := rows.Scan(&rec.ID, &rec.Name, &rec.Email, &rec.Data); err != nil {
			continue
		}
		results = append(results, rec)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
